import React, { useState } from "react";
import BuyActionWindow from "./BuyActionWindow";

const GeneralContext = React.createContext({
  openBuyWindow: (uid) => {},
  closeBuyWindow: () => {},
  openSellWindow: (uid) => {}, // Naya function define kiya
});

export const GeneralContextProvider = (props) => {
  const [isBuyWindowOpen, setIsBuyWindowOpen] = useState(false);
  const [isSellWindowOpen, setIsSellWindowOpen] = useState(false); // Sell ke liye state
  const [selectedStockUID, setSelectedStockUID] = useState("");

  const handleOpenBuyWindow = (uid) => {
    setIsBuyWindowOpen(true);
    setIsSellWindowOpen(false); // Ensure karein ki ek baar mein ek hi window khule
    setSelectedStockUID(uid);
  };

  const handleOpenSellWindow = (uid) => {
    setIsSellWindowOpen(true);
    setIsBuyWindowOpen(false); // Buy window band kar dein agar khuli ho
    setSelectedStockUID(uid);
  };

  const handleCloseBuyWindow = () => {
    setIsBuyWindowOpen(false);
    setIsSellWindowOpen(false);
    setSelectedStockUID("");
  };

  return (
    <GeneralContext.Provider
      value={{
        openBuyWindow: handleOpenBuyWindow,
        closeBuyWindow: handleCloseBuyWindow,
        openSellWindow: handleOpenSellWindow, // Value mein pass kiya
      }}
    >
      {props.children}

      {/* Buy Window render karein mode="BUY" ke saath */}
      {isBuyWindowOpen && (
        <BuyActionWindow uid={selectedStockUID} mode="BUY" />
      )}

      {/* Sell Window render karein mode="SELL" ke saath */}
      {isSellWindowOpen && (
        <BuyActionWindow uid={selectedStockUID} mode="SELL" />
      )}
    </GeneralContext.Provider>
  );
};

export default GeneralContext;
